using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(nameof(Chat_RespondsRelevantly));

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluator = new RelevancyEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, chatClient);

        await scenario.ReportAsync(result);

        Assert.IsTrue(
            result.All(r => r.Rating >= EvaluationRating.Good),
            "Response did not meet relevancy threshold.");
    }

    [TestMethod]
    public async Task Chat_RespondsCoherently()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(nameof(Chat_RespondsCoherently));

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in simple terms.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluator = new CoherenceEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response, chatClient);

        await scenario.ReportAsync(result);

        Assert.IsTrue(
            result.All(r => r.Rating >= EvaluationRating.Good),
            "Response did not meet coherence threshold.");
    }

    [TestMethod]
    public async Task Chat_MultiTurnConversation()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(nameof(Chat_MultiTurnConversation));

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to learn about machine learning."),
        };

        var response1 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "Can you give me a specific example?"));

        var response2 = await chatClient.GetResponseAsync(messages);

        var evaluator = new RelevancyEvaluator();
        var result = await evaluator.EvaluateAsync(messages, response2, chatClient);

        await scenario.ReportAsync(result);

        Assert.IsTrue(
            result.All(r => r.Rating >= EvaluationRating.Good),
            "Multi-turn response did not meet relevancy threshold.");
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storagePath = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-results");

        return DiskBasedReportingConfiguration.Create(storageDirectory: storagePath);
    }
}

